    fun offerInGallery(path: String): Boolean = path in galleryFiles || (path !in allFiles && path !in legacyBundledFiles)
    fun variant(item: AacItem, male: Boolean): String? {
        val pair = gendered[item.id] ?: return null
        return AacSystemImagePolicy.select(item.iconSource.name, item.imagePath, item.userEdited, item.locked,
            pair.legacy + setOf(pair.female, pair.male), pair.female, pair.male, male)
    }
